INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('APT', 'apt', 'Agricultural Partnerships for Transformation (APT) is a Zimbabwean development organisation working with smallholder farmers and rural communities to build more resilient, productive and sustainable food and farming systems. APT promotes agroecological approaches that strengthen food and nutrition security, improve rural livelihoods and connect farmers more effectively to markets, working through partnerships with communities, government, civil society and the private sector. Its emphasis is on locally led solutions that are practical, inclusive and capable of continuing and scaling beyond individual projects.', 'https://apt.co.zw')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Africa Ahead', 'africa-ahead', 'Africa AHEAD is a Zimbabwean NGO that empowers communities to achieve sustainable improvements in health, wellbeing and resilience through participatory, locally led development. Its approach strengthens community structures, local capacity and collective action to support sustainable and inclusive development.', 'https://www.africaahead.org')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Bethany', 'bethany', 'Bethany Project is a registered Private Voluntary Organisation (PVO 2/98). It is a child- and youth-centred organisation whose niche is the protection, empowerment, and development of children and young people.', 'https://thebethanyproject.co.zw')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('DAPP', 'dapp', 'Development Aid from People to People Zimbabwe is a locally registered Private Voluntary Organization that has been dedicated to social development in Zimbabwe since its registration in June 1980. DAPP Zimbabwe complements the government efforts through implementing short and long-term development project activities in (1) Education, (2) Health, (3) Agriculture, (4) Community Development and (5) Emergencies aligned with national strategies and Sustainable Development Goals (SDGs).', 'https://www.dapp-zimbabwe.org/')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('CAFOD', 'cafod', 'CAFOD is the official Catholic aid agency for England and Wales tackling poverty and injustice across the world. CAFOD has been working in Zimbabwe since the 1970s, delivering humanitarian, resilience, and development programmes through strong partnerships with local civil society organizations, faith-based institutions, community structures, and government stakeholders.', 'https://cafod.org.uk/')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Alfred Walter Hostel', 'alfred-walter-hostel', 'Alfred Walter Hostel is a residential care and boarding facility located in Masvingo, Zimbabwe, that provides a warm home, specialized care, and skills training for about 150 children and youth with intellectual and mental challenges.', '')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Caritas Chinhoyi', 'caritas-chinhoyi', 'Caritas Chinhoyi is the development arm of the Catholic Diocese of Chinhoyi in Zimbabwe, committed to promoting human dignity, social justice, and sustainable community development in Rushinga, Mbire, Hurungwe, and Chinhoyi. Through partnerships with communities, government, and development partners, it implements programmes in child protection, gender equality, disability inclusion, food security, climate resilience, WASH, and livelihoods, prioritising the most vulnerable and marginalised. Guided by Catholic Social Teaching, Caritas Chinhoyi works to build resilient, inclusive, and empowered communities.', 'https://caritaschinhoyizim.org')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Caritas Masvingo', 'caritas-masvingo', 'Caritas Masvingo provides humanitarian assistance, promotes sustainable agriculture, and supports community development in the Masvingo province.', 'https://caritasmasvingozim.co.zw/')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Caritas Mutare', 'caritas-mutare', 'Caritas Mutare is the official charitable and development arm of the Diocese of Mutare, operating within the mission of the Catholic Church to proclaim the Gospel through concrete acts of charity, justice, and service. Rooted in Sacred Scripture and Catholic Social Teaching, Caritas Mutare exists to uphold the dignity of every human person, promote solidarity with the poor and vulnerable, and contribute to sustainable development within communities served by the Diocese.', 'https://caritasmutare.org/')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('St Alberts Mission', 'st-alberts-mission', 'Shamwari Dzevanhu St Alberts Mission (SDSAM) is a women-led, Private Voluntary Organization which is faith based (Catholic Church) in Zimbabwe dedicated to advancing the dignity, rights and wellbeing of women, girls, people with disabilities and vulnerable communities. Through community-based health, gender justice, GBV prevention, livelihoods, WASH and social support programmes, SDSAM works with communities and partners to build safer, more inclusive and resilient families across Mashonaland Central Province.', 'https://stalbertsmissionhospital.org/')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('CARE', 'care', 'CARE has worked in Zimbabwe since 1992, driving lasting change through six connected impact areas: gender equality, including education; food, water and nutrition security; economic empowerment that makes markets and financial products work for women; health solutions co-created with communities; climate resilience through adaptation and innovation; and humanitarian response that delivers urgent, flexible aid when crises strike.', 'https://www.carezimbabwe.org/')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('ZimWorks', 'zimworks', 'ZimWorX provides business process outsourcing (BPO) and remote staffing solutions, creating sustainable employment opportunities and career development for Zimbabwean youth.', 'https://zimworx.com/')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Childline', 'childline', 'Childline Zimbabwe operates the national free 24-hour helpline (116) service, providing therapeutic interventions and case management services for children on issues such as abuse, exploitation, mental health and suicide prevention. Childline works at improving child and family well-being, strengthening community-based support systems, challenging harmful gender and parenting norms and enhancing coordination within child protection systems.', 'https://www.childline.org.zw')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Council for the Blind', 'council-for-the-blind', 'The Zimbabwe Council for the Blind (ZCfB) is a leading eye health organisation established in 1955, dedicated to preventing avoidable blindness and improving access to affordable, quality eye care across Zimbabwe. Its services include comprehensive eye care, cataract surgeries, minor and major ophthalmic surgeries, community outreach, school vision screening, inclusive education, low vision care, rehabilitation, and issuance of affordable spectacles. Guided by its strategic direction, “Restoring Sight, Empowering Lives,” ZCfB works with the Government of Zimbabwe and partners towards a nation free from avoidable blindness.', 'https://councilfortheblind.org.zw/')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Education Matters', 'education-matters', 'Education Matters helps high-achieving, low-income African students access international educational opportunities through programs like the USAP Community School.', 'https://www.edmattersafrica.org/')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Ele Collection', 'ele-collection', 'Ele-Collection is a pioneering African circular economy company tackling plastic pollution while empowering women through meaningful employment and economic opportunity. At the heart of our work are women-led collection teams who recover plastic waste from communities and the environment, creating livelihoods while protecting wildlife and natural ecosystems. By transforming this waste into sustainable building materials, we are building a circular economy where women are central to driving lasting environmental, social and economic change.', 'https://elecollection.co/')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('FOST', 'fost', 'FOST is a Private Voluntary Organization (PVO3/97), registered in 1997, which solicits and facilitates support for orphans and vulnerable children and youth in farm communities in Zimbabwe. The FOST programme is based on the belief that orphaned children have the best opportunity for development within a family group, without sibling separation, in an environment that is familiar and where they have the opportunity to learn their culture firsthand.', 'https://www.fost.co.zw')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('FACE', 'face', 'Family Action for Community Empowerment in Zimbabwe is a Zimbabwean Private Voluntary Organization (PVO) working to empower marginalized communities, particularly women, young people, children and persons with disabilities. Its work focuses on social and economic empowerment, resilient livelihoods and environmental sustainability, and improved access to quality basic services, including health, hygiene, education and vocational training.', 'https://www.facezim.org')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Family Support', 'family-support', 'Family Support Trust is a Zimbabwean non governmental organization that prevents and responds to sexual and gender based violence. The organization runs 6 survivor friendly clinics that attend to women and girls who have experienced sexual and gender based violence. It also conducts prevention activities in the communities that are meant to prevent women and girls from being abused.', 'https://www.fst.co.zw')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('ARC', 'arc', 'Adult Rape Clinic (ARC) PVO 61/18 is a Zimbabwean survivor-centered non-governmental organization dedicated to restoring the health, dignity, hope and economic resilience of survivors of sexual and gender-based violence through comprehensive medical, psychosocial, medico-legal, referral and economic empowerment support. Since 2009, ARC has combined frontline care, community engagement, livelihoods strengthening, training, research and advocacy to help survivors recover, rebuild their lives and access their sexual and reproductive health and rights.', 'https://adultrapeclinic.org/')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Friendship Bench', 'friendship-bench', 'Friendship Bench is a Zimbabwean organisation that brings evidence-based mental health support into marginalised communities by training lay health workers, often grandmothers, to deliver structured Problem-Solving Therapy on simple wooden benches. Founded in Harare by psychiatrist Professor Dixon Chibanda, its model has been proven effective in clinical trials and is now being adapted in countries around the world.', 'https://www.friendshipbenchzimbabwe.org/')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Foundations for Farming', 'foundations-for-farming', 'Foundations for Farming is a Zimbabwe-based organisation dedicated to transforming lives and communities through faithful stewardship of the land, combining biblical principles with practical, sustainable farming methods. Through training, partnerships and innovative technologies, we equip farmers and agricultural extension officers to improve productivity, restore their land and build resilient livelihoods, producing more with what God has put in their hands.', 'https://www.foundationsforfarming.org.zw')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
