INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Kapnek', 'kapnek', 'JF Kapnek Zimbabwe is a national non-profit organisation advancing the health, protection, inclusion and wellbeing of vulnerable children, families and communities across Zimbabwe. Through locally led partnerships, the organisation works across public health, disability inclusion, early childhood development, safeguarding and child protection, combining direct service delivery with capacity strengthening, systems change and advocacy. JF Kapnek Zimbabwe is committed to strengthening local institutions and community systems so that sustainable, inclusive solutions are embedded beyond individual projects.', 'https://www.jfkapnek.org/')
