INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Mavambo', 'mavambo', 'Mavambo Orphan Care was established to create a healthy self-sustaining community for all children in Zimbabwe by complementing the efforts of the Government. Its mission is empowering children to develop their maximum potential to become socially adjusted, self-sustaining, and healthy responsible citizens. It provides educational, child protection, accelerated literacy, school feeding, vocational skills’ trainings, legal, birth registration, mental health and psychosocial support, capacity building, health and Hygiene, Livelihood (economic strengthening) and parenting and mentoring for girls and support families and caregivers.', 'https://www.mavambotrust.org.zw')
