INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('MASO', 'maso', 'For over 30 years, MASO has championed resilience and sustainable development programmes in Zimbabwe. Guided by its vision of "Building Resilient Communities for Sustainable Development", MASO drives lasting impact among vulnerable communities through climate action, environmental stewardship, health and well-being, and evidence-based programming.', 'https://www.maso.org.zw')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Mashamba', 'mashamba', 'Mashambanzou Care Trust (MCT) is a faith based Private Voluntary Organisation founded in Harare in 1989 in response to the suffering, stigma and social exclusion experienced by people living with HIV. MCT has evolved into an integrated health and social-development organisation serving vulnerable people and underserved communities while remaining grounded in its founding commitment to compassion, dignity and practical care. MCT’s vision is an AIDS-free, resilient and empowered communities and the mission is to contribute to healthy and socially inclusive communities, free from AIDS, through the provision of comprehensive HIV and integrated health services, support for orphans and vulnerable children, and community support and strengthening initiatives.', 'https://www.mashambanzoucaretrust.com')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
