INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Lesedi', 'lesedi', 'Lesedi Community Projects (LCP) is a local, community-based organisation whose mission is to reduce intergenerational poverty among vulnerable communities in Hwange and Victoria Falls, Matabeleland North. Our core thematic areas are quality inclusive education, primary health care, and broadening young people''s employment chances through technical and vocational skills training. The crosscutting elements of our work include gender, climate action, and environmental protection.', 'https://lesedizim.org')
