INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('SAT', 'sat', 'Established in 2007, Sustainable Agriculture Technology (SAT) is a Zimbabwean NGO advancing rural development and sustainable livelihoods through viable agribusiness models for smallholder farmers. Through the Mwenezi Youth Vocational Skills Training Centre, spearheaded by SAT with support from the OAK Foundation, it equips young people with practical skills in metal fabrication, solar systems and drip irrigation installation—creating pathways to employment, entrepreneurship and climate-smart rural development.', 'https://www.satzim.org.zw/')
