INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Simukai', 'simukai', 'Simukai Child Protection Programme responds to children facing separation, displacement, street-connectedness, abuse, exploitation and other protection risks. Simukai provides an integrated continuum of protection, care and reintegration services for vulnerable children and families. Its intervention model combines immediate protection with longer-term pathways to stability, integrating safeguarding, emergency shelter, case management, psychosocial support, education support, family tracing and reunification, birth registration support, livelihoods and vocational skills development.', 'https://www.simukaicpp.org.zw')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Terres Des Homme', 'terres-des-homme', 'Terre des Hommes Italia (TDH) is an international non-governmental organisation committed to protecting children''s rights and supporting vulnerable communities. TDH implements integrated programmes in child protection, education, gender equality, food security and nutrition, agroecology, climate resilience and humanitarian assistance. Working closely with government institutions, local partners and communities, TDH promotes sustainable development, social inclusion and resilience, including among refugees and host communities. Guided by its vision of a world where every child can grow up safe, free from violence and discrimination, and able to fulfil their potential, TDH places child protection at the heart of its mission and approach.', 'https://terredeshommes.it/eng/')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
