INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Uncommon', 'uncommon', 'Uncommon.org builds technology hubs in low-income communities and trains unemployed youth to become software engineers and tech educators, creating high-impact pathways to formal digital employment.', 'https://www.uncommon.org/')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Youth Advocates', 'youth-advocates', 'Youth Advocates is a youth-led Zimbabwean non-governmental organisation founded in 2004. Its mission is to empower all adolescents and youth with the knowledge, skills, resources and opportunities for healthy productive and fulfilling lives. Building integrated, youth-led systems of support that move young people from crisis to stability and economic independence. Through its 393 Youth Helpline, community programmes and digital platforms, it connects adolescents and young people to health services, psychosocial support, protection from violence and economic opportunities.', 'https://www.yadvocates.org')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Swiss Zim Aid', 'swiss-zim-aid', 'SwiZim Trust is a dynamic for-impact organization dedicated to fostering holistic community impact in Zimbabwe and was established in 2020. Through comprehensive educational programs, entrepreneurial support, and psycho-social initiatives, SwiZim Trust empowers individuals to unlock their potential and drive holistic impactful change. Its core programs are anchored on supporting young people for economic empowerment through self-designed learning in safe spaces called nooks.', 'https://swizimtrust.com/')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('ACT', 'act', 'Aids Counselling Trust (ACT Zimbabwe) is dedicated to improving the quality of life for vulnerable communities through comprehensive counseling, community health, psychosocial support, and advocacy.', 'https://www.actzimbabwe.org.zw')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Rafiq Girls', 'rafiq-girls', 'Founded in 2002, Rafiki (Rafiki Girls Centre) is a non-profit organisation with a mission to empower girls and young women experiencing social and economic disadvantage through education, vocational skills development, mentorship and livelihood opportunities. Rafiki emerged in response to challenges faced by young women who lost parental care and access to education and economic opportunities during the HIV and AIDS crisis, and has since evolved to address broader barriers to education, livelihoods and social inclusion.', 'https://www.rafikigirlscentre.org')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Restless Development', 'restless-development', 'Restless Development Zimbabwe is a youth-led development organisation that has worked in Zimbabwe since 1985. It partners with young people, especially those aged 10 to 35 who are most marginalised, so their voices shape decisions on health, livelihoods and communities. Its 2025–2030 strategy focuses on youth leadership, sexual and reproductive health and gender justice, livelihoods, and climate justice.', 'https://www.restlessdevelopment.org')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Young Africa', 'young-africa', 'Young Africa provides technical and vocational education and training (TVET) integrated with life skills and entrepreneurship training to empower marginalized youth.', 'https://youngafrica.org/zimbabwe/')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Chiedza', 'chiedza', 'Chiedza is a community-based organisation formed in 2001 in Harare, Zimbabwe. The organization is committed to providing education access, retention, completion, and employability services for vulnerable children and young people. It empowers vulnerable children and young people to overcome barriers, realise their potential, and build brighter futures.', 'https://www.chiedza.org')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Don Bosco Hwange', 'don-bosco-hwange', 'Don Bosco Technical College is a private, non-profit, Catholic institution located in the mining town of Hwange, Zimbabwe, run by the Salesians of Don Bosco dedicated towards youth ministry through education and skills training. Our mission is to empower disadvantaged youth, particularly from socio-economically vulnerable backgrounds, through high-quality Technical and Vocational Education and Training (TVET). A HEXCO accredited institution, it offers courses from National Foundation Certificate to Diploma level, fostering "Good Christians and Skillful Responsible Citizens."', 'https://donboscohwg.co.zw/')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('Deaf Zimbabwe Trust', 'deaf-zimbabwe-trust', 'Deaf Zimbabwe Trust is a convener, connector, and catalyst for change, increasing the social and economic power of persons with disabilities in Zimbabwe and their families. Deaf Zimbabwe Trust is a national cross-disability rights organization that advocates for the full civil rights of over 1.2 million people with disabilities and their families by promoting equal opportunity, economic power, independent living, and political participation. DZT uses 5 strategic pathways namely, Media and Outreach, Strategic actions and advocacy, building activist leadership, generating knowledge and learning from practice as well as building and mobilizing persons with disabilities and their families for social justice and access.', 'https://deafzimbabwetrust.org.zw')
ON CONFLICT (name) DO UPDATE SET description = EXCLUDED.description, website = EXCLUDED.website, directory_slug = EXCLUDED.directory_slug;
INSERT INTO public.partners (name, directory_slug, description, website)
VALUES ('ZIMCARE', 'zimcare', 'ZIMCARE Trust is registered private voluntary organization that offers quality care and education to children and adults with intellectual disabilities. We have 14 schools across Zimbabwe.', 'https://www.zimcaretrust.org')
